import itertools, builtins
def alts(e):
    x,y,z=e; c=[]
    for mid in range(3):
        a=[v+180 for v in e]; a[mid]=180-e[mid]; c.append(a)
    return c
def pick(m,o,prev):
    e=list(m.extractRotates('srt',o))
    cands=[e]
    for a in alts(e):
        mm=hou.hmath.buildRotate(a,o)
        if all(abs(p-q)<1e-4 for p,q in zip(mm.asTuple(),m.extractRotationMatrix3().asTuple() if False else hou.hmath.buildRotate(e,o).asTuple())): cands.append(a)
    if prev is None: return e
    best=None
    for c in cands:
        c=list(c)
        for i in range(3):
            while c[i]-prev[i]>180: c[i]-=360
            while c[i]-prev[i]<-180: c[i]+=360
        d=sum(abs(c[i]-prev[i]) for i in range(3))
        if best is None or d<best[0]: best=(d,c)
    return best[1]
builtins.eulerpick=pick
